<?php
require_once '../includes/auth.php'; require_role('teacher'); require_once '../config/db.php';
$page_title='Hourly Attendance'; $msg=''; $err=''; $teacher=$_SESSION['username'];
require_once '../includes/teacher_context.php';
$date=$_GET['date']??$_POST['attendance_date']??date('Y-m-d');$slotId=(int)($_GET['slot_id']??$_POST['timetable_id']??0);
$days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday'];$dayNo=(int)date('N',strtotime($date));

if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_hourly_attendance'])){
    $slotId=(int)$_POST['timetable_id'];$statuses=$_POST['status']??[];if(!is_array($statuses))$statuses=[];
    $st=$conn->prepare("SELECT tt.id,tt.batch_id,tt.hour_no,tt.subject,b.semester FROM tbl_timetable tt JOIN tbl_batches b ON b.id=tt.batch_id WHERE tt.id=? AND tt.teacher_username=? AND tt.batch_id=? AND tt.semester=? AND tt.day_of_week=?");$st->bind_param('isiii',$slotId,$teacher,$teacher_context_batch_id,$teacher_context_semester,$dayNo);$st->execute();$slot=$st->get_result()->fetch_assoc();
    if(!$slot){$err='That hour is not assigned to you for the selected batch/semester and date.';}else{
        $students=$conn->prepare("SELECT username FROM tbl_student WHERE approved=1 AND batch_id=?");$students->bind_param('i',$slot['batch_id']);$students->execute();$sr=$students->get_result();
        $up=$conn->prepare("INSERT INTO tbl_hourly_attendance(timetable_id,student_username,attendance_date,status,marked_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),marked_by=VALUES(marked_by)");
        $up->bind_param('issss',$slotId,$student,$date,$status,$teacher);while($s=$sr->fetch_assoc()){$student=$s['username'];$status=(isset($statuses[$student])&&$statuses[$student]==='Absent')?'Absent':'Present';$up->execute();}$msg='Attendance saved for Hour '.$slot['hour_no'].' · '.$slot['subject'].'.';
    }
}

$slotList=[];
if($teacher_context_batch){$slots=$conn->prepare("SELECT tt.id,tt.hour_no,tt.subject,tt.start_time,tt.end_time,b.batch_name FROM tbl_timetable tt JOIN tbl_batches b ON b.id=tt.batch_id WHERE tt.teacher_username=? AND tt.batch_id=? AND tt.semester=? AND tt.day_of_week=? ORDER BY tt.hour_no");$slots->bind_param('siii',$teacher,$teacher_context_batch_id,$teacher_context_semester,$dayNo);$slots->execute();$slotRows=$slots->get_result();while($r=$slotRows->fetch_assoc())$slotList[]=$r;}
$slot=null;$marked=[];
if($slotId && $teacher_context_batch){$st=$conn->prepare("SELECT tt.*,b.batch_name FROM tbl_timetable tt JOIN tbl_batches b ON b.id=tt.batch_id WHERE tt.id=? AND tt.teacher_username=? AND tt.batch_id=? AND tt.semester=?");$st->bind_param('isii',$slotId,$teacher,$teacher_context_batch_id,$teacher_context_semester);$st->execute();$slot=$st->get_result()->fetch_assoc();}
if($slot){$st=$conn->prepare("SELECT student_username,status FROM tbl_hourly_attendance WHERE timetable_id=? AND attendance_date=?");$st->bind_param('is',$slotId,$date);$st->execute();$r=$st->get_result();while($x=$r->fetch_assoc())$marked[$x['student_username']]=$x['status'];$students=$conn->prepare("SELECT username,name,course FROM tbl_student WHERE approved=1 AND batch_id=? ORDER BY name");$students->bind_param('i',$slot['batch_id']);$students->execute();$studentRows=$students->get_result();}
require '../includes/header.php';
?>
<div class="glass-hero mb-4"><div><span class="eyebrow-dark">ATTENDANCE</span><h2>Hourly attendance</h2><p>Mark only the class assigned to you. Attendance is stored separately for every subject hour.</p></div><div class="hero-orb"><i class="fa-solid fa-user-check"></i></div></div>
<?php if($msg): ?><div class="alert alert-success glass-alert"><?php echo e($msg); ?></div><?php endif; ?><?php if($err): ?><div class="alert alert-danger glass-alert"><?php echo e($err); ?></div><?php endif; ?>
<?php if(!$teacher_context_batch): ?><div class="context-warning mb-4"><i class="fa-solid fa-layer-group"></i><div><strong>Select your teaching context first</strong><p>Choose the batch and semester from your teacher dashboard. This controls which class hours you can access.</p><a href="dashboard.php">Go to Teacher Dashboard</a></div></div><?php endif; ?>
<div class="glass-card mb-4"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3"><div><div class="section-kicker">CLASS CONTEXT</div><h5><?php echo e(teacher_context_label()); ?></h5><span class="small-muted"><?php echo e($days[$dayNo]); ?> · <?php echo date('d M Y',strtotime($date)); ?></span></div><form method="GET" class="d-flex gap-2 align-items-end"><div><label class="form-label">Date</label><input class="form-control" type="date" name="date" value="<?php echo e($date); ?>" max="<?php echo date('Y-m-d'); ?>"></div><button class="btn btn-light">Load</button></form></div></div>
<div class="row g-4"><div class="col-lg-4"><div class="glass-card"><div class="section-kicker">YOUR HOURS</div><h5><?php echo e($days[$dayNo]); ?></h5><div class="d-grid gap-2 mt-3"><?php if(!$slotList): ?><div class="empty">No class is assigned to you for this batch on this day.</div><?php endif; ?><?php foreach($slotList as $s): ?><a class="slot-card <?php echo $slotId==(int)$s['id']?'selected':''; ?>" href="?date=<?php echo e($date); ?>&slot_id=<?php echo (int)$s['id']; ?>"><span>Hour <?php echo (int)$s['hour_no']; ?></span><strong><?php echo e($s['subject']); ?></strong><small><?php echo e($s['batch_name']); ?> · <?php echo e(substr($s['start_time'],0,5)); ?>–<?php echo e(substr($s['end_time'],0,5)); ?></small></a><?php endforeach; ?></div></div></div>
<div class="col-lg-8"><?php if($slot): ?><div class="glass-card"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><div><div class="section-kicker">MARKING NOW</div><h5>Hour <?php echo (int)$slot['hour_no']; ?> · <?php echo e($slot['subject']); ?></h5><span class="small-muted"><?php echo e($slot['batch_name']); ?> · <?php echo e(substr($slot['start_time'],0,5)); ?>–<?php echo e(substr($slot['end_time'],0,5)); ?></span></div><div class="d-flex gap-2"><button type="button" class="btn btn-sm btn-outline-success" onclick="setAllHourly('Present')">All Present</button><button type="button" class="btn btn-sm btn-outline-danger" onclick="setAllHourly('Absent')">All Absent</button></div></div><form method="POST" class="mt-3"><input type="hidden" name="save_hourly_attendance" value="1"><input type="hidden" name="attendance_date" value="<?php echo e($date); ?>"><input type="hidden" name="timetable_id" value="<?php echo (int)$slot['id']; ?>"><div class="table-responsive"><table class="table attendance-table"><thead><tr><th>Student</th><th>Present</th><th>Absent</th></tr></thead><tbody><?php while($s=$studentRows->fetch_assoc()):$v=$marked[$s['username']]??'Present'; ?><tr><td><strong><?php echo e($s['name']); ?></strong><br><span class="small-muted"><?php echo e($s['username']); ?></span></td><td class="text-center"><label class="attendance-choice present-choice"><input class="hourly-radio" type="radio" name="status[<?php echo e($s['username']); ?>]" value="Present" <?php echo $v==='Present'?'checked':''; ?>><span>Present</span></label></td><td class="text-center"><label class="attendance-choice absent-choice"><input class="hourly-radio" type="radio" name="status[<?php echo e($s['username']); ?>]" value="Absent" <?php echo $v==='Absent'?'checked':''; ?>><span>Absent</span></label></td></tr><?php endwhile; ?></tbody></table></div><button class="btn btn-primary w-100 mt-2"><i class="fa-solid fa-floppy-disk"></i> Save Hour Attendance</button></form></div><?php else: ?><div class="glass-card empty"><i class="fa-solid fa-calendar-clock fa-2x mb-3"></i><h5>Select your class hour</h5><p>Choose one of your scheduled hours to mark its students.</p></div><?php endif; ?></div></div>
<script>function setAllHourly(v){document.querySelectorAll('.hourly-radio').forEach(r=>{if(r.value===v)r.checked=true;});}</script>
<?php require '../includes/footer.php'; ?>
